def video_stitching(clips, target):
    farthest = [0] * target
    for start, end in clips:
        if start < target:
            farthest[start] = max(farthest[start], end)

    clips_used = 0
    covered = 0
    last_end = 0

    i = 0
    while covered < target:
        if i > covered:
            return -1
        while i <= covered and i < target:
            last_end = max(last_end, farthest[i])
            i += 1
        if last_end <= covered:
            return -1
        clips_used += 1
        covered = last_end

    return clips_used

